<script setup lang="ts">
import { computed,ref } from 'vue'
import { Pause,Volume2,VolumeX,Skull,PawPrint,ChevronUp,Radio,Shield } from '@lucide/vue'
import { ARSENAL,WEAPON_IDS,DISTRICTS,POWERS,type PowerKind } from '@/data/content'
import { loadout,settings } from '@/stores/profile'
import type { GameState,WeaponKind } from '@/types/game'
const props=defineProps<{state:Readonly<GameState>;muted:boolean}>();const emit=defineEmits<{weapon:[kind:WeaponKind];pause:[];sound:[];dog:[order:string]}>();const arsenal=ref(false);const w=computed(()=>ARSENAL[props.state.weapon]);const time=(s:number)=>`${Math.floor(s/60).toString().padStart(2,'0')}:${Math.floor(s%60).toString().padStart(2,'0')}`
</script>
<template>
 <header class="game-hud"><section class="vitals tactical-panel"><div class="vital-title"><span><i class="status-dot"/> {{loadout.operator==='assault'?'VEGA':loadout.operator==='scout'?'NOVA':loadout.operator==='support'?'CRUZ':'ROOK'}}</span><small>NIV. {{state.level}}</small></div><div class="hp-label"><span>INTEGRIDAD</span><strong data-testid="hud-health">{{Math.ceil(state.hp)}} <small>/ {{state.maxHp}}</small></strong></div><div class="bar health" role="progressbar" aria-label="Vida" :aria-valuenow="Math.ceil(state.hp)" :aria-valuemax="state.maxHp" :aria-valuemin="0"><i :style="{width:`${Math.max(0,state.hp/state.maxHp)*100}%`,background:state.hp<30?'var(--danger)':'var(--primary)'}"/></div><div class="armor-label"><Shield :size="10"/>{{Math.ceil(state.armor||0)}}<span>XP {{state.xp}} / {{state.xpNeeded}}</span></div><div class="bar xp"><i :style="{width:`${Math.min(100,state.xp/state.xpNeeded*100)}%`}"/></div></section><section class="wave-panel"><span class="tiny-label">{{loadout.mode==='campaign'?'OPERACIÓN EXTRACCIÓN':'RESISTENCIA INFINITA'}}</span><div>RONDA <strong data-testid="hud-wave">{{String(state.wave).padStart(2,'0')}}</strong><small v-if="loadout.mode==='campaign'">/ 10</small></div><p><Skull :size="12"/> {{state.kills}} <span/> {{time(state.elapsed)}}</p></section><div class="hud-right"><div class="hud-tools"><button data-testid="hud-sound" class="icon-button" :aria-label="muted?'Activar sonido':'Silenciar sonido'" @click="emit('sound')"><VolumeX v-if="muted"/><Volume2 v-else/></button><button data-testid="hud-pause" class="icon-button" aria-label="Pausar" @click="emit('pause')"><Pause/></button></div><div class="mini-map tactical-panel"><svg viewBox="0 0 180 62" aria-label="Mapa de los tres distritos"><rect x="3" y="3" width="174" height="56" fill="#1d2c3a"/><path d="M3 31H177 M33 3V59 M90 3V59 M147 3V59" stroke="#566173" stroke-width="4"/><path d="M60 3V59 M120 3V59" stroke="#8493a3" stroke-dasharray="2 3" stroke-width=".7"/><circle v-if="state.phase==='extract'" cx="148" cy="31" r="6" fill="none" stroke="#7be7d6"/><circle :cx="3+(state.playerX||600)/3600*174" :cy="3+(state.playerY||600)/1200*56" r="3" fill="#ffb454"/></svg><span>{{DISTRICTS[state.district||0]?.type}} · {{state.enemies}} hostiles</span></div></div></header>
 <div v-if="loadout.dog" class="dog-hud tactical-panel"><div><PawPrint :size="15"/><strong>ATLAS</strong><span data-testid="hud-dog-status">{{state.dogHp!==undefined&&state.dogHp<=0?state.dogStatus:`${Math.ceil(state.dogHp||0)} / 90`}}</span></div><div class="dog-orders"><button v-for="o in ['follow','defend','attack']" :key="o" :data-testid="`hud-dog-${o}`" :class="{active:state.dogOrder===o}" @click="emit('dog',o)">{{o==='follow'?'Seguir':o==='defend'?'Defender':'Atacar'}}</button></div></div>
 <div v-if="state.bossHp" class="boss-hud"><span>EL COLOSO / OBJETIVO FINAL</span><div class="bar"><i :style="{width:`${state.bossHp/(state.bossMax||1)*100}%`}"/></div></div>
 <div v-if="state.phase==='extract'" class="extraction-hud" data-testid="extraction-objective"><Radio :size="16"/><span>{{state.objective}}</span><strong>{{Math.round((state.extraction||0)/4*100)}}%</strong></div>
 <div v-if="settings.subtitles&&state.radio" class="radio-dialogue tactical-panel" data-testid="radio-dialogue"><Radio :size="18"/><div><span>{{state.radioSpeaker}}</span><p>{{state.radio}}</p></div><i class="radio-line"/></div>
 <div v-if="state.lastPickup" class="pickup-toast" role="status" data-testid="pickup-toast">{{state.lastPickup}}</div><div class="powerup-list" data-testid="active-powerups"><span v-for="p in state.powerups" :key="p.kind" :style="{color:POWERS[p.kind as PowerKind]?.color}"><b>{{POWERS[p.kind as PowerKind]?.icon}}</b>{{p.title}} {{Math.ceil(p.remaining)}} s</span></div>
 <section class="ammo-hud tactical-panel"><button data-testid="weapon-drawer-toggle" :aria-expanded="arsenal" aria-label="Abrir arsenal" @click="arsenal=!arsenal"><div><span class="tiny-label">{{w.category}}</span><strong data-testid="hud-weapon">{{w.title}}</strong></div><ChevronUp :size="17"/></button><div class="ammo-count" data-testid="hud-ammo"><strong>{{(state.reload||0)>0?'…':state.ammo}}</strong><span>/ {{state.reserve}}</span></div><div v-if="(state.reload||0)>0" class="reload-progress">RECARGANDO · {{state.reload?.toFixed(1)}} s</div><div v-if="arsenal" class="weapon-drawer"><button v-for="(id,i) in WEAPON_IDS" :key="id" :data-testid="`switch-${id}`" :class="{selected:state.weapon===id}" @click="emit('weapon',id);arsenal=false"><kbd>{{i+1}}</kbd>{{ARSENAL[id].title}}</button></div></section>
 <div v-if="settings.showFps" class="telemetry" data-testid="hud-fps"><i class="status-dot"/>{{state.fps}} FPS · {{settings.quality==='low'?'BAJA':settings.quality==='high'?'ALTA':'EQUILIBRADA'}}{{settings.auto?' / AUTO':''}}</div>
</template>
